// lib/mockups.ts — realistic garment mockups (generated by tools/mockups/generate_tee_mockups.py).
// Geometry here mirrors the generator. Logical space is the designer's 500x500 canvas.
import type { Product } from "@/lib/types";

export type TeeColor = "white" | "ash" | "black";
export type SymbolTone = "auto" | "white" | "black" | "green";

export const MONO_RATIO = 328 / 389; // height / width of the NE monogram files

/** Where customers may place artwork on the front of the tee. */
export const TEE_PRINT_AREA = { x: 140, y: 110, width: 220, height: 300 };
/** Default NE symbol: small, on the wearer's left chest (the right side as you look at the shirt). */
export const SYMBOL_DEFAULT = { x: 298, y: 127, width: 24 };
export const SYMBOL_MIN = 10;
export const SYMBOL_MAX = 120;

/** How strongly the white highlight layer shows on each fabric colour. */
const LIGHT_OPACITY: Record<TeeColor, number> = { white: 0, ash: 0.1, black: 0.55 };
/** Symbol colour chosen automatically for each garment colour. */
const AUTO_TONE: Record<TeeColor, Exclude<SymbolTone, "auto">> = { white: "green", ash: "black", black: "white" };

/** Map a colour name from the admin (White, Jet Black, Heather Ash...) to a mockup colour. */
export function teeColorKey(name?: string | null): TeeColor | null {
  const n = (name ?? "").toLowerCase();
  if (n.includes("white")) return "white";
  if (n.includes("black")) return "black";
  if (n.includes("ash") || n.includes("grey") || n.includes("gray") || n.includes("heather")) return "ash";
  return null;
}

/** True when this product has no photo of its own and should use the generated tee mockups. */
export function usesTeeMockup(product: Pick<Product, "category" | "images">): boolean {
  if (product.category !== "T-Shirts") return false;
  const first = product.images[0];
  return !first || first.startsWith("/mockups/");
}

export function teeLayers(color: TeeColor) {
  return {
    bare: `/mockups/tee-bare-${color}.png`,
    shade: "/mockups/tee-shade.png",
    light: "/mockups/tee-light.png",
    lightOpacity: LIGHT_OPACITY[color],
  };
}

export function symbolSrc(tone: SymbolTone, color: TeeColor): string {
  const t = tone === "auto" ? AUTO_TONE[color] : tone;
  return { white: "/brand/ne-monogram-white.png", black: "/brand/ne-monogram-black.png", green: "/brand/ne-monogram.png" }[t];
}

/** The picture to show for a product in the shop, product page and cart. */
export function productImage(product: Pick<Product, "category" | "images">, colorName?: string | null, withSymbol = true): string | null {
  const first = product.images[0];
  if (first && !first.startsWith("/mockups/")) return first;
  if (!usesTeeMockup(product)) return null;
  const key = teeColorKey(colorName) ?? "white";
  return `/mockups/tee-${key}${withSymbol ? "-symbol" : ""}.png`;
}
